const SECOND_DEFENDERS:Record<string,{name:string;rating:number;role:string}>={rma:{name:"D. Alaba",rating:85,role:"DEF"},mci:{name:"J. Gvardiol",rating:86,role:"DEF"},fcb:{name:"P. Cubarsí",rating:84,role:"DEF"},liv:{name:"I. Konaté",rating:85,role:"DEF"},riv:{name:"L. Martínez Quarta",rating:81,role:"DEF"},boc:{name:"L. Advíncula",rating:80,role:"DEF"},fla:{name:"Ayrton Lucas",rating:81,role:"DEF"},pal:{name:"Murilo",rating:82,role:"DEF"},arg:{name:"N. Otamendi",rating:85,role:"DEF"},fra:{name:"T. Hernández",rating:86,role:"DEF"},bra:{name:"Gabriel Magalhães",rating:86,role:"DEF"},por:{name:"N. Mendes",rating:86,role:"DEF"},ars:{name:"Gabriel Magalhães",rating:87,role:"DEF"},bay:{name:"K. Min-jae",rating:85,role:"DEF"},psg:{name:"Nuno Mendes",rating:86,role:"DEF"},atm:{name:"R. Le Normand",rating:84,role:"DEF"},esp:{name:"R. Le Normand",rating:85,role:"DEF"},eng:{name:"J. Stones",rating:85,role:"DEF"},ger:{name:"J. Tah",rating:85,role:"DEF"},uru:{name:"M. Olivera",rating:83,role:"DEF"},int:{name:"B. Pavard",rating:85,role:"DEF"},che:{name:"L. Colwill",rating:82,role:"DEF"}};
const teamRoster=(team:Team)=>{
  const pool=[...team.players];if(!pool.some(player=>player.role==="ARQ"))pool.push(MISSING_KEEPERS[team.id]??{name:`Arquero ${team.short}`,rating:team.rating-5,role:"ARQ"});
  pool.push(DEPTH_PLAYERS[team.id]??{name:`Reserva ${team.short}`,rating:team.rating-7,role:"MED"});
  const addRole=(role:string,name:string)=>pool.push({name,rating:team.rating-7,role});
  if(pool.filter(player=>player.role==="DEF").length<2)pool.push(SECOND_DEFENDERS[team.id]??{name:`Defensor ${team.short}`,rating:team.rating-7,role:"DEF"});
  while(pool.filter(player=>player.role==="DEF").length<2)addRole("DEF",`Lateral ${team.short}`);
  while(pool.filter(player=>player.role==="MED").length<2)addRole("MED",`Volante ${team.short}`);
  if(!pool.some(player=>player.role==="DEL"||player.role==="EXT"))addRole("DEL",`Delantero ${team.short}`);
  const byRating=(a:Team["players"][number],b:Team["players"][number])=>b.rating-a.rating,keeper=pool.find(player=>player.role==="ARQ")!;
  const attackers=pool.filter(player=>player.role==="DEL"||player.role==="EXT").sort(byRating),mids=pool.filter(player=>player.role==="MED").sort(byRating),defenders=pool.filter(player=>player.role==="DEF").sort(byRating);
  const starters=[attackers[0],mids[0],mids[1],defenders[0],defenders[1]],used=new Set(starters.map(player=>player.name));
  const bench=pool.filter(player=>player.role!=="ARQ"&&!used.has(player.name)).sort(byRating);
  return [...starters,...bench,keeper].slice(0,6).concat(keeper);
};
const defaultSelection=(count:PlayerCount)=>[...Array.from({length:count-1},(_,i)=>i),6];
const lineupFor=(team:Team,count:PlayerCount)=>{const pool=teamRoster(team),keeper=pool.find(player=>player.role==="ARQ")!;return [...pool.filter(player=>player.role!=="ARQ").slice(0,count-1),keeper]};
const unitRating=(team:Team,roles:string[])=>{const players=team.players.filter(player=>roles.includes(player.role));return players.length?Math.round(players.reduce((sum,player)=>sum+player.rating,0)/players.length):team.rating};

